(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*14;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.33)*12;
  const w2x = Math.sin((x+w1x)*0.012+t*0.15)*10 + Math.cos((y+w1y)*0.01-t*0.18)*8;
  const w2y = Math.cos((y+w1y)*0.014-t*0.17)*9 + Math.sin((x+w1x)*0.011+t*0.2)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [120+Math.sin(t*0.5)*90, 60+Math.cos(t*0.35)*40, 0.09, 2.2, 1.0],
    [360+Math.cos(t*0.45)*80, 70+Math.sin(t*0.55)*35, 0.11, 1.8, 0.8],
    [80+Math.cos(t*0.6+2)*70, 180+Math.sin(t*0.4+1)*50, 0.07, 2.5, 1.2],
    [400+Math.sin(t*0.38+3)*60, 190+Math.cos(t*0.5+2)*45, 0.08, 2.0, 0.9],
    [240+Math.sin(t*0.32+1)*130, 100+Math.cos(t*0.48)*70, 0.06, 2.8, 1.1],
    [200+Math.cos(t*0.42+4)*100, 180+Math.sin(t*0.58+3)*60, 0.1, 1.6, 0.7],
