    [160+Math.cos(t*0.52+2)*85, 220+Math.sin(t*0.37+4)*40, 0.095, 1.9, 0.85]
  ];
  let aS=0, iS=0, aW=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.55+1.8)*w;
    aW += Math.sin(d*f*1.3-t*sp*0.8+2.5)*w*0.4;
  }
  const tw=8, act=aS/tw, inh=iS/tw, aux=aW/tw;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    + Math.sin((sx+sy)*0.11+t*2.2)*0.2 + Math.sin((sx-sy)*0.095-t*1.8)*0.18
    + Math.sin(sx*0.06+t*1.4)*Math.sin(sy*0.055-t*1.1)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
