  const voronoi = (() => {
    let md = 1e9, md2 = 1e9;
    for (let i=0;i<src.length;i++) {
      const d = Math.sqrt((sx-src[i][0])**2+(sy-src[i][1])**2);
      if (d<md) { md2=md; md=d; } else if (d<md2) { md2=d; }
    }
    return Math.tanh((md2-md)*0.08)*0.25;
  })();
  const feedback = Math.tanh(act*0.6)*0.3 - Math.tanh(inh*0.5)*0.2;
  const reaction = Math.tanh((act-inh*0.65+bg*0.3+spiral+voronoi+aux*0.2+feedback)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.4+Math.sin(sx*0.08-sy*0.06+t*0.7)*0.3)*1.3)*0.25;
  const micro = Math.sin(sx*0.25+t*3)*Math.sin(sy*0.22-t*2.5)*0.08*reaction;
  const blend = reaction*0.65+cell*0.2+micro, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[12,45,88],[18,95,115],[25,155,135],[145,185,90],
    [225,195,55],[215,135,60],[185,75,70],[120,35,65],[50,15,55],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
